  const capitalizeFirstLetter = (str: string) =>
    str && typeof str === "string" && str.length > 0
      ? str[0].toUpperCase() + str.slice(1)
      : str;

  const constructFormData = (formsData: any, resetId?: number) => {
    // console.log("formData", formsData);
    let activeSupplierData = suppliersData.filter(
      (value: any, key: any) => value._id === activeSuppliers
    );

    let keyObjects = Object.keys(formsData);
    let formType = formsData.formType;
    let formId = formsData.formId;
    let lableNames: any = [];
    let fieldLabel: any = [];
    let fieldNames: any = [];
    let unitsName: any = [];
    let constructData: any = [];
    let activeSupplier;
    let checkNumber = /^(\d+ )*(\d+)$/;

    activeSupplierData.map((element: any) => {
      activeSupplier = element;
    });

    keyObjects.map((element: any) => {
      if (element.includes("&&&")) {
        fieldNames.push(element);
      } else if (element.includes("###")) {
        fieldLabel.push(element);
      } else if (element.includes("****")) {
        unitsName.push(element);
      } else if (
        element !== "formType" &&
        element !== "formId" &&
        !checkNumber.test(element)
      ) {
        lableNames.push(element);
      }
    });

    let getMatchedLen: any = [];

    lableNames.map((lebelName: any) => {
      getMatchedLen = [];
      fieldNames.map((fieldName: any) => {
        fieldLabel.map((fieldlabel: any) => {
          let exactFiledName = fieldName.split("&&&");
          let lableNames = fieldlabel.split("###");

          let name: any = exactFiledName[0];
          if (lableNames[0] === name) {
            if (fieldName.includes(lebelName)) {
              let display: any;
              if (formsData[fieldName] === "false") {
                display = {
                  value: "",
                  label: formsData[fieldlabel],
                  display: false,
                };
              } else if (
                formsData[fieldName] === "mm" ||
                formsData[fieldName] === "Kg" ||
                formsData[fieldName] === "% or °(Degree)" ||
                formsData[fieldName] === "Amps" ||
                formsData[fieldName] === "Volts" ||
                formsData[fieldName] === "W/Km" ||
                formsData[fieldName] === "Km/h" ||
                formsData[fieldName] === "Degrees"
              ) {
                // console.log(
                //   "Wheel_base&&&General_arrangement_vehicle",
                //   formsData[fieldName]
                // );
              } else {
                let units: string = "";
                for (const el of unitsName) {
                  let measureMent = el.split("****");
                  let fielsdName = fieldName.split("&&&");
                  if (measureMent[0] === fielsdName[0]) {
                    units = formsData[el];
                    break;
                  }
                }
                // if (units) {
                //     console.log('unitsData', units);
                //     display = {
                //         "value": formsData[fieldName],
                //         "label": formsData[fieldlabel],
                //         "units": units
                //     }
                // } else {

                //     display = {
                //         "value": formsData[fieldName],
                //         "label": formsData[fieldlabel],
                //     }
                // }

                // if (units) {
                //   display = {
                //     value: capitalizeFirstLetter(formsData[fieldName]), // ✅ Capitalized here
                //     label: formsData[fieldlabel],
                //     units: units,
                //   };
                // } else {
                //   display = {
                //     value: capitalizeFirstLetter(formsData[fieldName]), // ✅ Capitalized here
                //     label: formsData[fieldlabel],
                //   };
                // }

                let value = capitalizeFirstLetter(formsData[fieldName]);
                const label = formsData[fieldlabel];
                
                // ✅ Use actual label text to check if it's a date field
                const rawLabel = (formsData[fieldlabel] || "").toLowerCase();
                const knownDateLabels = ["tac validity", "date of submission"];
                const isDateField = knownDateLabels.some(dateLabel => rawLabel.includes(dateLabel));
                
                if (isDateField && typeof value === "string") {
                  // console.log('this is date before condition logic', value);
                  value = formatDateToDDMMYYYY(value);
                  // console.log('this is date after condition logic', value);
                }
                

                if (units) {
                    // console.log('unitsData', units);
                    display = {
                        value,
                        label,
                        units
                    };
                } else {
                    display = {
                        value,
                        label
                    };                                   
                }

              
              }

              getMatchedLen.push({ [name]: display });
            }
          }
        });
      });

      const feildObjects = getMatchedLen.reduce(
        (accumulator: any, currentValue: any) => {
          const key = Object.keys(currentValue)[0];
          accumulator[key] = currentValue[key];
          return accumulator;
        },
        {}
      );

      constructData.push({
        [lebelName]: {
          properties: feildObjects,
          label: lebelName.replace(/_/g, " "),
        },
      });
    });

    constructData.push({ supplier: activeSupplier });
    constructData.push({ _id: formId });

    const formsLabelObjects = constructData.reduce(
      (accumulator: any, currentValue: any) => {
        const key = Object.keys(currentValue)[0];
        accumulator[key] = currentValue[key];
        return accumulator;
      },
      {}
    );

    // console.log("constructData", {
    //   data: formsLabelObjects,
    //   formType: formType,
    // });
    storeFormsfieldDat(
      { data: formsLabelObjects, formType: formType },
      resetId
    );
  };

